-- Generated by scripts/build_compiled.py from src/fraudrules/rules/account-takeover/at-005-new-geo-device-then-mfa-change.yaml. Do not edit.
-- AT-005 Login from a new device in a new country, then an MFA change
SELECT DISTINCT
  'AT-005' AS rule_id,
  'events' AS anchor_table,
  s1.id AS anchor_id
FROM events AS s1
JOIN events AS s0
  ON s0.customer_id = s1.customer_id
  AND s0.ts < s1.ts
  AND s0.ts > s1.ts - 3600
  AND (
    s0.event_type = 'login'
    AND s0.outcome = 'success'
    AND s0.device_new = 1
    AND s0.geo_new = 1
  )
WHERE
  (
    s1.event_type = 'mfa_change' AND s1.outcome = 'success'
  );
